parameters.jsCode:
const body = $('Webhook').first().json.body;
let raw = String($input.first().json.text || '').replace(/```json|```/g, '').trim();
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
const exam = JSON.parse(raw.slice(s, e + 1));
const ar = body.lang === 'ar';
const esc = x => String(x ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const L = ar ? {weak:'ضعيف',average:'متوسط',top:'متفوق',ans:'الإجابة',why:'التوضيح',hi:'أهلاً',intro:'أسئلتك جاهزة:'} : {weak:'Weak',average:'Average',top:'Advanced',ans:'Answer',why:'Explanation',hi:'Hello',intro:'Your questions are ready:'};
const col = {weak:'#d99a1e',average:'#1c7c54',top:'#b4432b'};
const items = exam.questions.map((q,i)=>`<div style="padding:16px 0;border-top:1px solid #ded8c6"><div style="font-weight:700;font-size:16px;color:#1d2a24"><span style="background:${col[q.level]||'#1c7c54'};color:#fff;border-radius:99px;padding:1px 10px;font-size:12px;margin-${ar?'left':'right'}:8px">${L[q.level]||''}</span>${i+1}. ${esc(q.q)}</div>${(q.options||[]).map((o,j)=>`<div style="color:#677068;padding:2px 12px">${'ABCD'[j]||j+1}. ${esc(o)}</div>`).join('')}<div style="margin-top:8px;padding:8px 12px;border-radius:10px;background:#e3f1ea;color:#1c7c54;font-size:14px"><b>${L.ans}:</b> ${esc(q.answer)}${q.explanation?`<br><b>${L.why}:</b> ${esc(q.explanation)}`:''}</div></div>`).join('');
const html = `<div dir="${ar?'rtl':'ltr'}" style="background:#f3efe4;padding:24px;font-family:Tahoma,Arial,sans-serif"><div style="max-width:680px;margin:auto;background:#fffdf7;border:1px solid #ded8c6;border-radius:18px;overflow:hidden"><div style="background:#1c7c54;color:#fff;padding:18px 28px;font-size:18px;font-weight:700">${ar?'صانع الامتحانات':'Exam Maker'}</div><div style="padding:28px"><h1 style="margin:0 0 6px;font-size:24px;color:#1d2a24">${esc(exam.title)}</h1><p style="color:#677068;margin:0 0 16px">${L.hi} ${esc(body.name)}، ${L.intro}</p>${items}</div></div></div>`;
return [{ json: { exam, html, email: body.email, subject: exam.title || 'Exam' } }];
